import asyncioimport subprocessimport sysimport timeimport collectionsimport discordimport yt_dlpimport mathimport osimport configparserimport reimport unicodedataimport deamstoolsimport aiohttpfrom urllib.parse import urlparse, parse_qsfrom main import bot, logw, api, log, add_help, FFMPEG_PATH, is_owner, logerr, loge, vcinuse_flags, logdconfig_file = 'MusicConfig.ini'cookiefile = 'cookie.txt'MusicConfig = configparser.ConfigParser(interpolation=None)default_config = {    'Messages': {        'Loading': '🎧 Loading... `[{query}]`',        'PlaybackResumed': '🎶 Playback resumed!',        'PlaybackPaused': '⏸ Playback paused.',        'PlaybackStopped': '⏹ Playback stopped and queue cleared.',        'QueueEmpty': '🎶 Your queue is currently empty.',        'NowPlaying': '🎵 Now playing: **[{title}](<{url}>)**',        'SongAdded': '➕ Added **{title}** to the queue at position {position}.',        'VolumeSet': '🔊 Volume set to {volume}%.',        'CurrentVolume': '🔊 Current volume: {volume}%.',        'PlaylistImport': 'Importing playlist... Found {count} songs',        'PlaylistImported': 'Successfully imported {count} songs from playlist: **{title}**',        'PlaylistChoice': 'This video is part of a playlist. React with:\n🎵 - Import just this video\n📋 - Import entire playlist ({count} songs)',    },    'Defaults': {        'Volume': '1.0',        'RepeatMode': 'all',        'SeamlessTransition': 'false',        'CrossfadeDuration': '3',        'Autoplay': 'false',    },    'account': {        'username': '',        'password': '',        'cookie': 'cookie.txt',    },    'lastfm': {        # Get a free key at https://www.last.fm/api/account/create        'api_key': '',    },}if not os.path.exists(config_file):    MusicConfig.read_dict(default_config)    with open(config_file, 'w', encoding='utf-8') as configfile:        MusicConfig.write(configfile)else:    MusicConfig.read(config_file, encoding='utf-8')# Inject missing keys into existing configs without overwriting user valuesfor section, values in default_config.items():    if not MusicConfig.has_section(section):        MusicConfig.add_section(section)    for key, value in values.items():        if not MusicConfig.has_option(section, key):            MusicConfig.set(section, key, value)messages = MusicConfig['Messages']YDL_OPTIONS = {    'format': 'bestaudio[ext=webm]/bestaudio',    'noplaylist': True,    'outtmpl': 'playing.%(ext)s',    'quiet': True,    'no_warnings': True,    'default_search': 'auto',    'verbose': False,    'cookies': MusicConfig['account']['cookie'],}YDL_PLAYLIST_OPTIONS = {    'format': 'bestaudio[ext=webm]/bestaudio',    'quiet': True,    'no_warnings': True,    'extract_flat': True,    'cookies': MusicConfig['account']['cookie'],}if (MusicConfig['account']['username'] and MusicConfig['account']['username']) != '':    YDL_OPTIONS['username'] = MusicConfig['account']['username']    YDL_OPTIONS['password'] = MusicConfig['account']['password']    YDL_PLAYLIST_OPTIONS['username'] = MusicConfig['account']['username']    YDL_PLAYLIST_OPTIONS['password'] = MusicConfig['account']['password']CROSSFADE_DURATION = int(MusicConfig.get('Defaults', 'CrossfadeDuration', fallback='3'))LASTFM_API_KEY = MusicConfig.get('lastfm', 'api_key', fallback='')# How many song URLs to remember to prevent autoplay repeatsAUTOPLAY_HISTORY_SIZE = 50class CrossfadeSource(discord.AudioSource):    FRAME_LENGTH     = 20    SAMPLE_RATE      = 48000    CHANNELS         = 2    BYTES_PER_SAMPLE = 2    FRAME_SIZE = int(SAMPLE_RATE * CHANNELS * BYTES_PER_SAMPLE * FRAME_LENGTH / 1000)    def __init__(self, old_url: str, new_url: str,                 crossfade_duration: int, volume: float,                 seek_pos: int = 0, ffmpeg_path: str = 'ffmpeg'):        self.volume              = volume        self._done               = False        self._crossfade_duration = crossfade_duration        d = crossfade_duration        filter_complex = (            f'[0:a]afade=t=out:st=0:d={d},volume={volume}[outa];'            f'[1:a]afade=t=in:st=0:d={d},volume={volume}[outb];'            f'[outa][outb]amix=inputs=2:normalize=0:duration=shortest[mix]'        )        cmd = [            ffmpeg_path,            # Old song — seek to playback position before opening the stream            '-ss', str(seek_pos),            '-reconnect', '1', '-reconnect_streamed', '1', '-reconnect_delay_max', '5',            '-i', old_url,            # New song — start from beginning            '-reconnect', '1', '-reconnect_streamed', '1', '-reconnect_delay_max', '5',            '-i', new_url,            '-filter_complex', filter_complex,            '-map', '[mix]',            '-ac', str(self.CHANNELS),            '-ar', str(self.SAMPLE_RATE),            # Output duration — this is what actually limits the crossfade length            '-t', str(d),            '-f', 's16le',            '-loglevel', 'error',            'pipe:1',        ]        logd(f'[CrossfadeSource] cmd: seek_pos={seek_pos}s duration={d}s')        self._process = subprocess.Popen(            cmd,            stdout=subprocess.PIPE,            stderr=subprocess.PIPE,        )    def read(self) -> bytes:        if self._done:            return b''        chunk = self._process.stdout.read(self.FRAME_SIZE)        if not chunk:            self._done = True            # Drain stderr for debug            err = self._process.stderr.read().decode(errors='replace').strip()            if err:                logd(f'[CrossfadeSource] ffmpeg stderr: {err}')            logd('[CrossfadeSource] stdout exhausted — crossfade complete')            return b''        if len(chunk) < self.FRAME_SIZE:            chunk += b'\x00' * (self.FRAME_SIZE - len(chunk))        return chunk    @property    def is_opus(self) -> bool:        return False    def cleanup(self):        try:            if self._process.poll() is None:                self._process.kill()                self._process.wait(timeout=2)            self._process.stdout.close()            self._process.stderr.close()        except Exception as e:            logd(f'[CrossfadeSource] cleanup error: {e}')def check_yt_dlp():    log('Checking for Yt DLP update')    code = deamstools.check_for_package_updates('yt-dlp')[1]    if code == 200:        log('YT DLP Upto Date!')    elif code == 404:        logerr('Error Getting YT Dlp Error')    elif code == 202:        logw('YT DLP Outdated, Restart bot to update!')        subprocess.run([sys.executable, '-m', 'pip', 'install', '-U', 'yt-dlp'])    else:        loge('Error checking for YT Dlp update')    return codecheck_yt_dlp()server_data = {}load_locks = {}playlists_folder = 'Playlists'playlist_choice_timeout = 30# ─── Server state ─────────────────────────────────────────────────────────────def get_server_data(guild_id):    """Get or create per-guild state dict.    Queue entries are 4-tuples: (url, title, duration_seconds, is_autoplay)    current_song follows the same format.    """    if guild_id not in server_data:        server_data[guild_id] = {            'queue': [],            'repeat_mode': MusicConfig.get('Defaults', 'RepeatMode'),            'current_song': (None, None, None, False),            'stopped': False,            'volume': float(MusicConfig.get('Defaults', 'Volume')),            'paused_by_user': False,            'seamless': MusicConfig.getboolean('Defaults', 'SeamlessTransition', fallback=False),            'autoplay': MusicConfig.getboolean('Defaults', 'Autoplay', fallback=False),            # Pre-buffer            'next_stream_url': None,            'next_task': None,            'play_start_time': None,            # Autoplay            'autoplay_task': None,            # deque of recently played URLs; used to avoid repeats            'recently_played': collections.deque(maxlen=AUTOPLAY_HISTORY_SIZE),            '_old_stream_url':         None,            '_crossfade_trigger_task': None,            '_crossfading': False        }    return server_data[guild_id]def get_load_lock(guild_id):    if guild_id not in load_locks:        load_locks[guild_id] = asyncio.Lock()    return load_locks[guild_id]# ─── URL helpers ──────────────────────────────────────────────────────────────def is_playlist_url(url):    try:        parsed = urlparse(url)        if 'youtube.com' in parsed.netloc or 'youtu.be' in parsed.netloc:            if 'list=' in url or '/playlist' in parsed.path:                return True        return False    except Exception:        return Falsedef is_video_in_playlist(url):    try:        parsed = urlparse(url)        if 'youtube.com' in parsed.netloc:            qp = parse_qs(parsed.query)            return 'v' in qp and 'list' in qp and qp['list'][0] != ''        return False    except Exception:        return Falsedef extract_playlist_id_from_video_url(url):    try:        qp = parse_qs(urlparse(url).query)        pid = qp.get('list', [None])[0]        if pid and pid.strip() and not pid.startswith('WL'):            return pid    except Exception:        pass    return Nonedef get_video_id_from_url(url):    try:        parsed = urlparse(url)        if 'youtube.com' in parsed.netloc:            return parse_qs(parsed.query).get('v', [None])[0]        elif 'youtu.be' in parsed.netloc:            return parsed.path[1:]    except Exception:        pass    return Nonedef normalize_to_playlist_url(url):    pid = extract_playlist_id_from_video_url(url)    return f"https://www.youtube.com/playlist?list={pid}" if pid else url# ─── Autoplay: similar song discovery ─────────────────────────────────────────async def _get_related_via_youtube(url: str, recently_played: collections.deque):    """Pull related_videos from yt-dlp and return the first unseen entry."""    try:        def _extract():            opts = {                'quiet': True,                'no_warnings': True,                'extract_flat': True,                'skip_download': True,                'noplaylist': True,            }            if MusicConfig['account']['cookie'] and os.path.exists(MusicConfig['account']['cookie']):                opts['cookies'] = MusicConfig['account']['cookie']            with yt_dlp.YoutubeDL(opts) as ydl:                return ydl.extract_info(url, download=False)        info = await asyncio.to_thread(_extract)        related = info.get('related_videos') or []        for entry in related:            vid_id = entry.get('id')            vid_title = entry.get('title', '')            if not vid_id or not vid_title:                continue            candidate_url = f"https://www.youtube.com/watch?v={vid_id}"            if candidate_url in recently_played:                continue            log(f'[autoplay] YouTube related: {vid_title}')            return candidate_url, vid_title, entry.get('duration')    except Exception as e:        print(f'[autoplay] YouTube related extraction failed: {e}')    return None, None, NoneAUTOPLAY_MAX_DURATION = 12 * 60  # 12 minutes — rejects compilations and hour loopsSKIP_KEYWORDS = (    'hour', 'hours', 'hr ', 'compilation', 'mix', 'playlist',    'loop', 'nonstop', 'non-stop', 'full album', 'megamix',    'extended', 'marathon', 'continuous',)def _is_valid_autoplay_duration(duration) -> bool:    """Rejects None durations and anything suspiciously long."""    if duration is None:        return False  # unknown duration — safer to skip than queue a 3hr mix    return duration <= AUTOPLAY_MAX_DURATIONasync def _get_related_via_lastfm(title: str, recently_played: collections.deque):    if not LASTFM_API_KEY:        return None, None, None    artist, track = '', title    if ' - ' in title:        parts = title.split(' - ', 1)        artist, track = parts[0].strip(), parts[1].strip()    logd(f'[lastfm] Querying: artist="{artist}" track="{track}"')    try:        async with aiohttp.ClientSession() as session:            # ── Step 1: resolve artist via track.search if missing ────────────            if not artist:                async with session.get('https://ws.audioscrobbler.com/2.0/', params={                    'method': 'track.search',                    'track': track,                    'api_key': LASTFM_API_KEY,                    'format': 'json',                    'limit': '1',                }, timeout=aiohttp.ClientTimeout(total=8)) as resp:                    if resp.status == 200:                        data = await resp.json()                        matches = data.get('results', {}).get('trackmatches', {}).get('track', [])                        if matches:                            artist = matches[0].get('artist', '')                            logd(f'[lastfm] Resolved artist via search: "{artist}"')            # ── Step 2: try track.getSimilar ──────────────────────────────────            similar = []            if artist:                params = {                    'method': 'track.getSimilar',                    'track': track,                    'artist': artist,                    'limit': '10',                    'autocorrect': '1',                    'api_key': LASTFM_API_KEY,                    'format': 'json',                }                async with session.get('https://ws.audioscrobbler.com/2.0/',                        params=params,                        timeout=aiohttp.ClientTimeout(total=8)) as resp:                    if resp.status == 200:                        data = await resp.json()                        similar = data.get('similartracks', {}).get('track', [])                        logd(f'[lastfm] track.getSimilar found: {len(similar)}')            # ── Step 3: fall back to artist.getSimilar if needed ─────────────            if not similar and artist:                logd(f'[lastfm] Falling back to artist.getSimilar for "{artist}"')                async with session.get('https://ws.audioscrobbler.com/2.0/', params={                    'method': 'artist.getSimilar',                    'artist': artist,                    'api_key': LASTFM_API_KEY,                    'format': 'json',                    'limit': '10',                    'autocorrect': '1',                }, timeout=aiohttp.ClientTimeout(total=8)) as resp:                    if resp.status == 200:                        data = await resp.json()                        # Normalise to same shape as similartracks entries                        for a in data.get('similarartists', {}).get('artist', []):                            similar.append({'name': a['name'], 'artist': {'name': a['name']}})                        logd(f'[lastfm] artist.getSimilar found: {len(similar)}')        # ── Step 4: search YouTube for the first unseen result ────────────────        for t in similar:            lfm_artist = t.get('artist', {}).get('name', '')            lfm_name   = t.get('name', lfm_artist)   # artist.getSimilar has no track name            if not lfm_name:                continue            query = f"{lfm_artist} - {lfm_name}" if lfm_artist and lfm_name != lfm_artist else lfm_name            def _yt_search(q):                with yt_dlp.YoutubeDL({'quiet': True}) as ydl:                    info = ydl.extract_info(f'ytsearch3:{q}', download=False)                    if info and 'entries' in info:                        return info['entries']                return []            # then in the loop, replace the single-result check:            entries = await asyncio.to_thread(_yt_search, query)            for entry in entries:                if not entry:                    continue                res_url = entry.get('webpage_url', f"https://www.youtube.com/watch?v={entry['id']}")                res_title = entry.get('title', query)                res_dur = entry.get('duration')                if not _is_valid_autoplay_duration(res_dur):                    logd(f'[autoplay] Last.fm result too long ({fmt_duration(res_dur)}), skipping: {res_title}')                    continue                title_lower = res_title.lower()                if any(kw in title_lower for kw in SKIP_KEYWORDS):                    logd(f'[autoplay] Last.fm result looks like compilation, skipping: {res_title}')                    continue                if res_url not in recently_played:                    log(f'[autoplay] Last.fm → YouTube: {res_title}')                    return res_url, res_title, res_dur    except Exception as e:        print(f'[autoplay] Last.fm fallback failed: {e}')    return None, None, Noneasync def _get_related_via_ytsearch(title: str, recently_played: collections.deque):    queries = []    if ' - ' in title:        artist, track = title.split(' - ', 1)        artist = artist.strip()        track = track.strip()        clean_track = re.sub(r'\(.*?\)|\[.*?\]', '', track).strip()        queries = [            f'{artist} {clean_track}',       # most specific first            f'{artist} official',            f'{artist}',        ]    else:        clean = re.sub(r'\(.*?\)|\[.*?\]', '', title).strip()        queries = [            f'{clean} official',            f'{clean}',        ]    # Keywords that strongly indicate compilations, loops, or megamixes    SKIP_KEYWORDS = (        'hour', 'hours', 'hr ', 'compilation', 'mix', 'playlist',        'loop', 'nonstop', 'non-stop', 'full album', 'megamix',        'extended', 'marathon', 'continuous',    )    def _yt_search(q):        opts = {            'quiet': True,            'no_warnings': True,            'extract_flat': True,            'default_search': 'ytsearch8',        }        if MusicConfig['account']['cookie'] and os.path.exists(MusicConfig['account']['cookie']):            opts['cookies'] = MusicConfig['account']['cookie']        with yt_dlp.YoutubeDL(opts) as ydl:            info = ydl.extract_info(f'ytsearch8:{q}', download=False)            if info and 'entries' in info:                return info['entries']        return []    for query in queries:        try:            entries = await asyncio.to_thread(_yt_search, query)            for entry in entries:                if not entry:                    continue                vid_id    = entry.get('id')                vid_title = entry.get('title', '')                duration  = entry.get('duration')                if not vid_id or not vid_title:                    continue                # Duration gate — reject compilations and hour loops                if not _is_valid_autoplay_duration(duration):                    logd(f'[autoplay] Skipping long video ({fmt_duration(duration)}): {vid_title}')                    continue                # Title keyword gate                title_lower = vid_title.lower()                if any(kw in title_lower for kw in SKIP_KEYWORDS):                    logd(f'[autoplay] Skipping compilation-like title: {vid_title}')                    continue                candidate_url = f"https://www.youtube.com/watch?v={vid_id}"                if candidate_url in recently_played:                    continue                if title.lower()[:20] in vid_title.lower():                    continue                logd(f'[autoplay] ytsearch hit: {vid_title} ({fmt_duration(duration)}) (query: {query})')                return candidate_url, vid_title, duration        except Exception as e:            logd(f'[autoplay] ytsearch failed for "{query}": {e}')            continue    return None, None, Noneasync def _find_similar_song(seed_url: str, seed_title: str,                             recently_played: collections.deque):    """Try Last.fm first for quality, fall back to YouTube search."""    # Try Last.fm if key is set — highest quality results    if LASTFM_API_KEY:        url, title, duration = await _get_related_via_lastfm(seed_title, recently_played)        if url:            return url, title, duration    # Try YouTube related_videos (works when JS challenge solving works)    url, title, duration = await _get_related_via_youtube(seed_url, recently_played)    if url:        return url, title, duration    # Always-reliable fallback: plain YouTube search    url, title, duration = await _get_related_via_ytsearch(seed_title, recently_played)    if url:        return url, title, duration    return None, None, Noneasync def _ensure_autoplay_queued(ctx, seed_url: str, seed_title: str):    await asyncio.sleep(1)    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if not data['autoplay']:        return    if data['queue'] and data['queue'][-1][3]:        return    if data['repeat_mode'] in ('all', 'single'):        data['autoplay'] = True  # keep the setting but just don't queue        logd('[autoplay] Skipping — repeat mode is active')        return    # Try current seed, then fall back to recently played songs as seeds    seeds = [(seed_url, seed_title)]    for entry in reversed(list(data['recently_played'])):        if entry != seed_url:            seeds.append((entry, ''))  # title unknown but url is enough        if len(seeds) >= 3:            break    for s_url, s_title in seeds:        try:            url, title, duration = await _find_similar_song(                s_url, s_title or seed_title, data['recently_played']            )            if url:                title = sanitize_title(title)                data['queue'].append((url, title, duration, True))                logd(f'[autoplay] Queued: {title}')                if len(data['queue']) == 1 and not data.get('next_stream_url'):                    _schedule_prefetch(guild_id)                return        except Exception as e:            logd(f'[autoplay] Seed {s_url} failed: {e}')            continue    log('[autoplay] No similar song found after all seeds exhausted.')def _schedule_autoplay(ctx, seed_url: str, seed_title: str):    """Cancel any running autoplay task and start a fresh one."""    guild_id = ctx.guild.id    data = get_server_data(guild_id)    t = data.get('autoplay_task')    if t and not t.done():        t.cancel()    data['autoplay_task'] = bot.loop.create_task(        _ensure_autoplay_queued(ctx, seed_url, seed_title)    )# ─── Pre-buffer ───────────────────────────────────────────────────────────────async def _prefetch_next(guild_id):    data = get_server_data(guild_id)    data['next_stream_url'] = None    # Note: _old_stream_url is NOT reset here — _schedule_crossfade_trigger owns it    if not data['queue']:        logd('[prefetch] Queue empty, nothing to prefetch')        return    entry = data['queue'][0]    url, title = entry[0], entry[1]    logd(f'[prefetch] Resolving next stream: {title}')    t0 = time.time()    try:        stream_url = await get_stream_url(url)        data['next_stream_url'] = stream_url        logd(f'[prefetch] Next stream ready in {(time.time()-t0)*1000:.0f}ms')    except Exception as e:        logd(f'[prefetch] Next stream failed: {e}')def _schedule_prefetch(guild_id, delay: float = 0.0):    data = get_server_data(guild_id)    t = data.get('next_task')    if t and not t.done():        t.cancel()    async def _run():        if delay > 0:            await asyncio.sleep(delay)        await _prefetch_next(guild_id)    data['next_task'] = bot.loop.create_task(_run())# ─── Audio source builder ─────────────────────────────────────────────────────def _make_audio_source(stream_url: str, volume: float,                        fade_in: bool = False, fade_out_at: int | None = None):    fade_filters = []    if fade_in:        fade_filters.append(f'afade=t=in:st=0:d={CROSSFADE_DURATION}')    if fade_out_at is not None:        fade_filters.append(f'afade=t=out:st={fade_out_at}:d={CROSSFADE_DURATION}')    options = '-vn'    if fade_filters:        options += ' -af ' + ','.join(fade_filters)    source = discord.FFmpegPCMAudio(        stream_url,        executable=FFMPEG_PATH,        before_options='-reconnect 1 -reconnect_streamed 1 -reconnect_delay_max 5 -err_detect ignore_err',        options=options,    )    return discord.PCMVolumeTransformer(source, volume=volume)# ─── Core playback ────────────────────────────────────────────────────────────# ─── Proactive crossfade scheduler ───────────────────────────────────────────# Near the top with CROSSFADE_DURATIONOLD_URL_PREFETCH_LEAD = 12  # seconds before crossfade trigger to resolve old URLdef _schedule_crossfade_trigger(ctx, guild_id: int, duration: float):    data = get_server_data(guild_id)    t = data.get('_crossfade_trigger_task')    if t and not t.done():        t.cancel()    if not data['seamless']:        return    # Step 1 fires OLD_URL_PREFETCH_LEAD seconds before the crossfade    # Step 2 fires 0.3s before the crossfade (the actual trigger)    prefetch_in = max(0.0, duration - CROSSFADE_DURATION - OLD_URL_PREFETCH_LEAD)    trigger_in  = max(0.0, duration - CROSSFADE_DURATION - 0.3)    logd(f'[crossfade_trigger] Scheduled: old_url_prefetch in {prefetch_in:.1f}s, '         f'trigger in {trigger_in:.1f}s '         f'(duration={duration:.1f}s, crossfade={CROSSFADE_DURATION}s, lead={OLD_URL_PREFETCH_LEAD}s)')    async def _run():        # ── Step 1: pre-resolve old stream URL while there is plenty of time ──        await asyncio.sleep(prefetch_in)        d = get_server_data(guild_id)        if d['stopped'] or not d['seamless']:            logd('[crossfade_trigger] Aborted before old-URL prefetch (stopped/seamless off)')            return        current_url = d['current_song'][0]        if current_url and not d.get('_old_stream_url'):            logd('[crossfade_trigger] Pre-resolving old stream URL...')            t0 = time.time()            try:                old_url = await get_stream_url(current_url)                d['_old_stream_url'] = old_url                logd(f'[crossfade_trigger] Old stream URL ready in {(time.time()-t0)*1000:.0f}ms')            except Exception as e:                logd(f'[crossfade_trigger] Old URL resolve failed: {e}')        else:            logd(f'[crossfade_trigger] Old URL already cached or no current song, skipping prefetch')        # ── Step 2: wait the remaining gap then fire play_next ────────────────        remaining = trigger_in - prefetch_in        if remaining > 0:            await asyncio.sleep(remaining)        d = get_server_data(guild_id)        if not d['seamless'] or d['stopped'] or d.get('paused_by_user'):            logd('[crossfade_trigger] Aborted before trigger')            return        if not d['queue']:            logd('[crossfade_trigger] No queue at trigger time')            return        vc = ctx.guild.voice_client        if not vc or not vc.is_playing():            logd('[crossfade_trigger] VC not playing at trigger time')            return        # Sanity check: confirm there's actually enough time left to crossfade        elapsed_now = (time.time() - d['play_start_time']) if d['play_start_time'] else 0        actual_time_left = (duration - elapsed_now) if duration else 0        logd(f'[crossfade_trigger] actual_time_left={actual_time_left:.2f}s at fire time')        if actual_time_left < 0.5:            logd('[crossfade_trigger] Too late to crossfade, skipping')            return        logd('[crossfade_trigger] Firing proactive play_next for crossfade')        d['_proactive_trigger'] = True        await play_next(ctx)    data['_crossfade_trigger_task'] = bot.loop.create_task(_run())async def play_next(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    vc = ctx.guild.voice_client    if not vc or not vc.is_connected():        if ctx.author.voice and ctx.author.voice.channel:            vc = await ctx.author.voice.channel.connect()        else:            await ctx.send('I need to be in a voice channel to play music!')            return    if not data['queue']:        data['current_song'] = (None, None, None, False)        if 'vcinuse_flags' in globals():            vcinuse_flags[str(ctx.guild.id)] = False        return    entry = data['queue'].pop(0)    url, title, duration = entry[0], entry[1], entry[2]    is_autoplay = entry[3] if len(entry) > 3 else False    if data['current_song'][0] is not None and not is_autoplay:        if data['repeat_mode'] == 'all':            data['queue'].append((url, title, duration, False))        elif data['repeat_mode'] == 'single':            data['queue'].insert(0, (url, title, duration, False))    proactive = data.pop('_proactive_trigger', False)    logd(f'[play_next] Starting: {title} (proactive={proactive})')    data['recently_played'].append(url)    t0 = time.time()    stream_url = data.pop('next_stream_url', None)    data['next_stream_url'] = None    if stream_url:        logd(f'[play_next] Used pre-buffered stream URL (0ms)')    else:        logd(f'[play_next] No pre-buffer, resolving now...')        stream_url = await get_stream_url(url)        logd(f'[play_next] Stream URL resolved in {(time.time()-t0)*1000:.0f}ms')    if not stream_url:        await ctx.send(f'❌ Failed to get stream URL for: **{title}**')        if data['queue']:            await play_next(ctx)        return    seamless = data['seamless']    volume   = data['volume']    current_url, _, current_dur, _ = data['current_song']    elapsed   = (time.time() - data['play_start_time']) if data['play_start_time'] else None    time_left = (current_dur - elapsed) if (current_dur and elapsed) else None    logd(f'[play_next] seamless={seamless}, vc.is_playing={vc.is_playing()}, '         f'time_left={f"{time_left:.1f}s" if time_left is not None else "unknown"}')    old_stream_url = data.pop('_old_stream_url', None)    do_crossfade = (        seamless        and proactive        and vc.is_playing()        and current_url is not None    )    logd(f'[play_next] do_crossfade={do_crossfade}, old_url_ready={old_stream_url is not None}')    if do_crossfade:        if not old_stream_url:            logd('[play_next] Old URL not pre-fetched, resolving live...')            t1 = time.time()            old_stream_url = await get_stream_url(current_url)            logd(f'[play_next] Old URL resolved in {(time.time()-t1)*1000:.0f}ms')        if old_stream_url:            seek_pos = int(elapsed) if elapsed else 0            logd(f'[play_next] Building CrossfadeSource (seek_pos={seek_pos}s, duration={CROSSFADE_DURATION}s)')            t2 = time.time()            cf_source = CrossfadeSource(                old_url=old_stream_url,                new_url=stream_url,                crossfade_duration=CROSSFADE_DURATION,                volume=volume,                seek_pos=seek_pos,                ffmpeg_path=FFMPEG_PATH,            )            logd(f'[play_next] CrossfadeSource spawned in {(time.time()-t2)*1000:.0f}ms')            data['_crossfading'] = True            data['current_song']    = (url, title, duration, is_autoplay)            data['play_start_time'] = time.time()            # ── Swap source directly — no vc.stop(), no gap ───────────────────            # discord.py's AudioPlayer thread calls source.read() in a loop.            # Replacing vc.source atomically swaps what it reads next frame.            # We also need to replace the after callback so when cf_source            # exhausts itself, the player calls our after_crossfade instead of            # whatever was registered before.            t3 = time.time()            player = vc._player            if player is not None:                # Swap the source — the player thread picks this up on the next                # read() call (within 20ms). No stop/start, no gap.                old_source = player.source                player.source = cf_source                # Swap the after callback                player.after = _make_crossfade_after(                    ctx, data, vc, cf_source, stream_url,                    url, title, duration, is_autoplay, volume                )                # Cleanup the old source (the original FFmpegPCMAudio)                try:                    old_source.cleanup()                except Exception:                    pass                logd(f'[play_next] Source swapped in {(time.time()-t3)*1000:.0f}ms — no stop/play gap')            else:                # Fallback: no player running, just play cf_source normally                logd('[play_next] No active player, starting cf_source via vc.play()')                vc.play(cf_source, after=_make_crossfade_after(                    ctx, data, vc, cf_source, stream_url,                    url, title, duration, is_autoplay, volume                ))        else:            logd('[play_next] Failed to get old stream URL, falling back to plain playback')            do_crossfade = False    if not do_crossfade:        logd('[play_next] Plain playback path')        t4 = time.time()        audio_source = _make_audio_source(stream_url, volume)        data['current_song']    = (url, title, duration, is_autoplay)        data['play_start_time'] = time.time()        if not data['stopped'] and not vc.is_playing():            vc.play(audio_source, after=lambda e: _handle_after_playback(                ctx, data, vc, url, title, duration, is_autoplay))            logd(f'[play_next] vc.play() called in {(time.time()-t4)*1000:.0f}ms')        else:            logd(f'[play_next] Skipped vc.play — stopped={data["stopped"]}, is_playing={vc.is_playing()}')    if seamless and duration and duration > CROSSFADE_DURATION * 2:        _schedule_crossfade_trigger(ctx, guild_id, duration)    if data['queue']:        _schedule_prefetch(guild_id, delay=0.0)    if data['autoplay']:        _schedule_autoplay(ctx, url, title)def _make_crossfade_after(ctx, data, vc, cf_source, stream_url,                           url, title, duration, is_autoplay, volume):    """Returns the after-callback to attach to the player during crossfade."""    def after_crossfade(err):        logd(f'[crossfade] Finished. err={err}')        data['_crossfading'] = False        try:            cf_source.cleanup()        except Exception:            pass        if data['stopped'] or not vc.is_connected():            return        remainder = _make_audio_source(stream_url, volume)        def after_remainder(err2):            if err2:                logd(f'[crossfade] Remainder error: {err2}')            _handle_after_playback(ctx, data, vc, url, title, duration, is_autoplay)        # The player has now exhausted cf_source and called this callback.        # We need to start the remainder — but the player is stopped now,        # so vc.play() is safe here.        vc.play(remainder, after=after_remainder)        logd('[crossfade] Remainder source started')    return after_crossfadedef _handle_after_playback(ctx, data, vc, url, title, duration, is_autoplay):    try:        if data.get('_crossfading'):            logd('[after_playback] Crossfade in flight, ignoring natural end callback')            return        if data['stopped']:            data['stopped'] = False            return        if data.get('paused_by_user'):            return        logd(f'[after_playback] Natural end for: {title}')        if data['queue']:            bot.loop.create_task(play_next(ctx))        else:            data['current_song'] = (None, None, None, False)            if 'vcinuse_flags' in globals():                vcinuse_flags[str(ctx.guild.id)] = False    except Exception as e:        logd(f'[after_playback] Exception: {e}')        print(f'Exception in after_playback: {e}')# ─── Info extraction ──────────────────────────────────────────────────────────async def get_playlist_info(playlist_url):    try:        def extract_playlist():            opts = {                'quiet': True, 'no_warnings': True, 'extract_flat': True,                'ignoreerrors': True, 'skip_download': True,                'playlistend': 100, 'no_color': True,            }            if MusicConfig['account']['cookie'] and os.path.exists(MusicConfig['account']['cookie']):                opts['cookies'] = MusicConfig['account']['cookie']            if (MusicConfig['account']['username'] and MusicConfig['account']['password']                    and MusicConfig['account']['username'] != ''):                opts['username'] = MusicConfig['account']['username']                opts['password'] = MusicConfig['account']['password']            with yt_dlp.YoutubeDL(opts) as ydl:                return ydl.extract_info(playlist_url, download=False)        info = await asyncio.to_thread(extract_playlist)        if not info:            return None, []        def _parse(entries_list):            out = []            for i, e in enumerate(entries_list):                if e and e.get('id'):                    out.append((                        f"https://www.youtube.com/watch?v={e['id']}",                        e.get('title', f'Video {i + 1}'),                        e.get('duration'),                    ))            return out        if info.get('_type') == 'playlist' and 'entries' in info:            return info.get('title', info.get('uploader', 'Unknown Playlist')), _parse(info['entries'])        elif info.get('_type') == 'url' and info.get('ie_key') == 'Youtube':            redirect = info.get('url') or info.get('webpage_url')            if redirect and redirect != playlist_url:                return await get_playlist_info(redirect)            return None, []        elif 'entries' not in info:            if info.get('id'):                return info.get('uploader', 'Single Video'), [(                    info.get('webpage_url', f"https://www.youtube.com/watch?v={info['id']}"),                    info.get('title', 'Unknown Title'),                    info.get('duration'),                )]            return None, []        else:            return info.get('title', 'Unknown Playlist'), _parse(info.get('entries', []))    except Exception as e:        print(f'Error extracting playlist info: {e}')        return None, []async def handle_video_in_playlist_choice(ctx, video_url):    playlist_id = extract_playlist_id_from_video_url(video_url)    if not playlist_id:        return video_url    playlist_url = normalize_to_playlist_url(video_url)    try:        _, entries = await get_playlist_info(playlist_url)        if not entries or len(entries) <= 1:            vid = get_video_id_from_url(video_url)            return f"https://www.youtube.com/watch?v={vid}" if vid else video_url        msg = await ctx.send(messages['PlaylistChoice'].format(count=len(entries)))        await msg.add_reaction('🎵')        await msg.add_reaction('📋')        def check(reaction, user):            return (user == ctx.author and str(reaction.emoji) in ['🎵', '📋']                    and reaction.message.id == msg.id)        try:            reaction, _ = await bot.wait_for('reaction_add', timeout=playlist_choice_timeout, check=check)            if str(reaction.emoji) == '📋':                await msg.edit(content=messages['Loading'].format(query='playlist'))                success = await import_playlist_to_queue(ctx, playlist_url, msg)                if success and not ctx.guild.voice_client.is_playing():                    await play_next(ctx)                return None            else:                await msg.delete()                vid = get_video_id_from_url(video_url)                return f"https://www.youtube.com/watch?v={vid}" if vid else video_url        except asyncio.TimeoutError:            await msg.edit(content='⏰ Choice timed out, importing just the video.')            await msg.clear_reactions()            vid = get_video_id_from_url(video_url)            return f"https://www.youtube.com/watch?v={vid}" if vid else video_url    except Exception as e:        print(f'Error getting playlist info for choice: {e}')        vid = get_video_id_from_url(video_url)        return f"https://www.youtube.com/watch?v={vid}" if vid else video_urlasync def get_song_info(query):    """Returns (title, url, duration_seconds)."""    try:        def _extract(q):            with yt_dlp.YoutubeDL({'quiet': True}) as ydl:                if 'youtube.com/watch' in q or 'youtu.be' in q:                    return ydl.extract_info(q, download=False)                return ydl.extract_info(f'ytsearch:{q}', download=False)        info = await asyncio.to_thread(_extract, query)        if 'entries' in info:            info = info['entries'][0]        return info.get('title', 'Unknown title'), info.get('webpage_url', query), info.get('duration')    except Exception as e:        print(f'Error retrieving song info: {e}')        return None, None, Noneasync def get_stream_url(url):    try:        def _extract():            opts = {'quiet': True, 'format': 'bestaudio/best', 'noplaylist': True}            if MusicConfig['account']['cookie'] and os.path.exists(MusicConfig['account']['cookie']):                opts['cookies'] = MusicConfig['account']['cookie']            with yt_dlp.YoutubeDL(opts) as ydl:                info = ydl.extract_info(url, download=False)                return info.get('url')        return await asyncio.to_thread(_extract)    except Exception as e:        print(f'Error getting stream URL: {e}')        return None# ─── Queue / display helpers ──────────────────────────────────────────────────def sanitize_title(title: str) -> str:    normalized = unicodedata.normalize('NFKD', title).encode('ASCII', 'ignore').decode('utf-8')    sanitized = re.sub(r'[\\/*?:"<>|]', '', normalized)    return re.sub(r'\s+', ' ', sanitized).strip()async def add_to_queue(ctx, query, is_autoplay=False):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    title, url, duration = await get_song_info(query)    if title is None:        return None, None, None, None    title = sanitize_title(title)    data['queue'].append((url, title, duration, is_autoplay))    return title, url, duration, len(data['queue'])async def import_playlist_to_queue(ctx, playlist_url, loading_message=None):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    playlist_url = normalize_to_playlist_url(playlist_url)    playlist_title, entries = await get_playlist_info(playlist_url)    if not entries:        msg = ('❌ Could not load playlist. This might be due to:\n'               '• Private playlist\n• Age-restricted content\n'               '• Geographic restrictions\n• YouTube API limitations\n\n'               'Try using individual video URLs instead.')        if loading_message:            await loading_message.edit(content=msg)        else:            await ctx.send(msg)        return False    if loading_message:        await loading_message.edit(content=messages['PlaylistImport'].format(count=len(entries)))    added = 0    for video_url, video_title, duration in entries:        try:            data['queue'].append((video_url, sanitize_title(video_title), duration, False))            added += 1        except Exception as e:            print(f'Error adding {video_title}: {e}')    msg = messages['PlaylistImported'].format(count=added, title=playlist_title)    if loading_message:        await loading_message.edit(content=msg)    else:        await ctx.send(msg)    return added > 0def fmt_duration(seconds) -> str:    if seconds is None:        return '?:??'    seconds = int(seconds)    h, rem = divmod(seconds, 3600)    m, s = divmod(rem, 60)    return f'{h}:{m:02d}:{s:02d}' if h else f'{m}:{s:02d}'def progress_bar(elapsed: float, total: float, width: int = 16) -> str:    if total <= 0:        return '▬' * width    ratio = min(elapsed / total, 1.0)    filled = round(ratio * width)    return '━' * filled + '🔘' + '─' * (width - filled)def build_now_playing_embed(data: dict) -> discord.Embed:    url, title, duration, is_autoplay = data['current_song']    elapsed = time.time() - data['play_start_time'] if data['play_start_time'] else None    embed = discord.Embed(color=discord.Color.from_rgb(88, 166, 255))    embed.set_author(name=('🤖 Autoplay  •  ' if is_autoplay else '') + 'Now Playing 🎵')    embed.title = title or 'Nothing'    if url:        embed.url = url    if duration and elapsed is not None:        embed.description = f'`{fmt_duration(elapsed)}` {progress_bar(elapsed, duration)} `{fmt_duration(duration)}`'    elif elapsed is not None:        embed.description = f'`{fmt_duration(elapsed)}` elapsed'    repeat_icons = {'all': '🔁 All', 'single': '🔂 One', 'off': '➡️ Off'}    footer_parts = [        f'🔊 {int(data["volume"] * 100)}%',        f'Repeat: {repeat_icons.get(data["repeat_mode"], data["repeat_mode"])}',    ]    if data['seamless']:        footer_parts.append('✨ Seamless')    if data['autoplay']:        footer_parts.append('🤖 Autoplay ON')    embed.set_footer(text='  •  '.join(footer_parts))    return embed# ─── Commands ─────────────────────────────────────────────────────────────────@bot.command(name='play', aliases=['p', 'P', 'Play'])async def play_command(ctx, *, query: str = None):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    data['stopped'] = False    if 'vcinuse_flags' in globals():        vcinuse_flags[str(ctx.guild.id)] = True    vc = ctx.guild.voice_client    if vc and vc.is_paused() and not query:        vc.resume()        data['paused_by_user'] = False        await ctx.send(messages['PlaybackResumed'])        return    if not query:        await ctx.send('Please provide a query or link')        return    if not ctx.author.voice:        await ctx.send('You are not connected to a voice channel!')        return    channel = ctx.author.voice.channel    if ctx.guild.voice_client:        if ctx.guild.voice_client.channel != channel:            await ctx.guild.voice_client.move_to(channel)    else:        await channel.connect()        await asyncio.sleep(2)    # Local playlist shorthand: !play pl <name>    if query.startswith('pl '):        playlist = query.replace('pl ', '', 1)        path = f'{playlists_folder}/{playlist}.txt'        if os.path.exists(path):            loading_msg = await ctx.send(f'Loading playlist {playlist}')            with open(path, 'r', encoding='utf-8') as f:                songs = f.readlines()            if not songs:                await ctx.send('Playlist is empty!')                return            count = 0            for song in songs:                if not song.strip():                    continue                await add_to_queue(ctx, song.strip())                if not ctx.guild.voice_client.is_playing():                    await play_next(ctx)                count += 1            await loading_msg.edit(content=f'Loaded {count} songs')            return    if is_video_in_playlist(query):        processed = await handle_video_in_playlist_choice(ctx, query)        if processed is None:            return        query = processed    if is_playlist_url(query):        loading_msg = await ctx.send(messages['Loading'].format(query=query))        success = await import_playlist_to_queue(ctx, query, loading_msg)        if success and not ctx.guild.voice_client.is_playing():            await play_next(ctx)        return    loading_msg = await ctx.send(messages['Loading'].format(query=query))    load_lock = get_load_lock(guild_id)    async with load_lock:        title, url, duration, position = await add_to_queue(ctx, query, is_autoplay=False)        if title is None:            await loading_msg.edit(content='❌ Could not find or load the song.')            return        title = sanitize_title(title)        if ctx.guild.voice_client.is_playing() or position > 1:            dur_str = f' `[{fmt_duration(duration)}]`' if duration else ''            await loading_msg.edit(                content=messages['SongAdded'].format(title=title, position=position) + dur_str            )            if position == 1 and not data.get('next_stream_url'):                _schedule_prefetch(guild_id)            return        if not ctx.guild.voice_client.is_playing():            await play_next(ctx)        if title:            await loading_msg.edit(content=messages['NowPlaying'].format(title=title, url=url))add_help('Music', 'play [search query/URL/playlist URL]',         'Searches YouTube with the provided query to play music, import playlists, or resume paused music')@bot.command(name='pause')async def pause_command(ctx):    data = get_server_data(ctx.guild.id)    vc = ctx.guild.voice_client    if vc and vc.is_playing():        vc.pause()        data['paused_by_user'] = True        await ctx.send(messages['PlaybackPaused'])    else:        await ctx.send('I am not playing anything right now!')@bot.command(name='resume')async def resume_command(ctx):    data = get_server_data(ctx.guild.id)    vc = ctx.guild.voice_client    if vc and vc.is_paused():        vc.resume()        data['paused_by_user'] = False        await ctx.send(messages['PlaybackResumed'])    else:        await ctx.send('I am not playing anything right now!')add_help('Music', 'resume', 'Resumes the player')@bot.command(name='skip', aliases=['next'])async def skip(ctx):    data = get_server_data(ctx.guild.id)    data['stopped'] = True    vc = ctx.guild.voice_client    if vc and vc.is_playing():        data['next_stream_url'] = None        for key in ('next_task', 'autoplay_task', '_crossfade_trigger_task'):            t = data.get(key)            if t and not t.done():                t.cancel()        data.pop('_proactive_trigger', None)        data['_crossfading'] = False        # Remove this — play_next now handles repeat        # entry = data['current_song']        # if not entry[3] and data['repeat_mode'] == 'all':        #     data['queue'].append(entry)        vc.stop()        await ctx.send('Skipped the current song.')        await play_next(ctx)    else:        await ctx.send('No song is currently playing to skip!')add_help('Music', 'skip', 'Skips the current song')@bot.command(name='skipto')async def skipto(ctx, position: int):    data = get_server_data(ctx.guild.id)    data['stopped'] = True    vc = ctx.guild.voice_client    if position < 1 or position > len(data['queue']):        await ctx.send('Invalid position in the queue!')        return    if vc and vc.is_playing():        data['next_stream_url'] = None        data['queue'].insert(0, data['current_song'])        data['queue'] = data['queue'][position:] + data['queue'][:position]        vc.stop()        await ctx.send(f'Skipped to position {position} in the queue.')        await play_next(ctx)    else:        await ctx.send('No song is currently playing!')add_help('Music', 'skipto <pos>', 'Skips to the given position in the queue')@bot.command(name='stop')async def stop(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    data['stopped'] = True    data['next_stream_url'] = None    for key in ('next_task', 'autoplay_task'):        t = data.get(key)        if t and not t.done():            t.cancel()    if 'vcinuse_flags' in globals():        vcinuse_flags[str(ctx.guild.id)] = False    vc = ctx.guild.voice_client    if vc:        for key in ('next_task', 'autoplay_task', '_crossfade_trigger_task'):            t = data.get(key)            if t and not t.done():                t.cancel()        data.pop('_proactive_trigger', None)        data['_crossfading'] = False        if vc.is_playing() or vc.is_paused():            vc.stop()        await vc.disconnect()        data['queue'] = []        data['current_song'] = (None, None, None, False)        if os.path.exists('playing.webm'):            os.remove('playing.webm')        await ctx.send(messages['PlaybackStopped'])    else:        await ctx.send('I am not connected to a voice channel!')add_help('Music', 'stop', 'Stops the player and clears the queue')@bot.command(name='volume', aliases=['vol'])async def set_volume(ctx, vol: int = None):    data = get_server_data(ctx.guild.id)    if vol is None:        await ctx.send(messages['CurrentVolume'].format(volume=int(data['volume'] * 100)))        return    if vol < 0 or vol > 200:        await ctx.send('Volume must be between 0 and 200')        return    data['volume'] = vol / 100.0    vc = ctx.guild.voice_client    if vc and vc.source:        vc.source.volume = data['volume']    await ctx.send(messages['VolumeSet'].format(volume=int(data['volume'] * 100)))add_help('Music', 'volume <percentage>', 'Sets the volume percentage')@bot.command(name='repeat', aliases=['r', 'loop'])async def repeat_command(ctx, mode: str = None):    data = get_server_data(ctx.guild.id)    if mode is None:        await ctx.send(f'Current repeat mode is **{data["repeat_mode"]}**.')        return    mode = mode.lower()    if mode in ('all', 'single', 'off'):        data['repeat_mode'] = mode        await ctx.send(f'Repeat mode set to **{data["repeat_mode"]}**.')    else:        await ctx.send('Invalid repeat mode. Use `all`, `single`, or `off`.')add_help('Music', 'repeat [all/single/off]', 'Shows or changes the loop/repeat setting')@bot.command(name='seamless', aliases=['sl', 'crossfade'])async def seamless_command(ctx, toggle: str = None):    """Toggle seamless transitions (pre-buffering + crossfade)."""    data = get_server_data(ctx.guild.id)    if toggle is None:        state = '✨ **ON**' if data['seamless'] else '**OFF**'        await ctx.send(f'Seamless transitions are currently {state}.')        return    t = toggle.lower()    if t in ('on', 'true', '1', 'enable', 'yes'):        data['seamless'] = True        await ctx.send(f'✨ Seamless transitions **enabled** — crossfade over {CROSSFADE_DURATION}s.')        if data['queue']:            _schedule_prefetch(ctx.guild.id)    elif t in ('off', 'false', '0', 'disable', 'no'):        data['seamless'] = False        data['next_stream_url'] = None        task = data.get('next_task')        if task and not task.done():            task.cancel()        await ctx.send('Seamless transitions **disabled**.')    else:        await ctx.send('Usage: `!seamless on` or `!seamless off`')add_help('Music', 'seamless [on/off]',         'Toggles seamless transitions: pre-buffers the next song and crossfades between tracks')@bot.command(name='autoplay', aliases=['ap', 'radio'])async def autoplay_command(ctx, toggle: str = None):    """Toggle autoplay radio mode — always keeps one similar song queued ahead."""    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if toggle is None:        state = '🤖 **ON**' if data['autoplay'] else '**OFF**'        await ctx.send(f'Autoplay is currently {state}.')        return    t = toggle.lower()    if t in ('on', 'true', '1', 'enable', 'yes'):        data['autoplay'] = True        sources = ('YouTube related videos + Last.fm fallback'                   if LASTFM_API_KEY                   else 'YouTube related videos *(add a Last.fm API key in MusicConfig.ini for richer results)*')        await ctx.send(f'🤖 Autoplay **enabled** — using {sources}.')        # If already playing, kick off discovery immediately        current = data['current_song']        if current[0]:            if not data['queue'] or not data['queue'][-1][3]:                _schedule_autoplay(ctx, current[0], current[1])    elif t in ('off', 'false', '0', 'disable', 'no'):        data['autoplay'] = False        # Trim autoplay entries from the tail of the queue        while data['queue'] and data['queue'][-1][3]:            data['queue'].pop()        task = data.get('autoplay_task')        if task and not task.done():            task.cancel()        await ctx.send('🤖 Autoplay **disabled**. Pending autoplay songs removed from queue.')    else:        await ctx.send('Usage: `!autoplay on` or `!autoplay off`')add_help('Music', 'autoplay [on/off]',         'Toggles autoplay radio mode — finds similar songs automatically so the music never stops. '         'Uses YouTube related videos with Last.fm as fallback. Autoplay songs are marked 🤖 in the queue.')@bot.command(name='queue', aliases=['q'])async def queue_list(ctx):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if not data['queue'] and data['current_song'][1] is None:        await ctx.send('📭 The queue is currently empty.')        return    queue = data['queue']    items_per_page = 10    pages = max(1, math.ceil(len(queue) / items_per_page))    def get_page_embed(page):        embed = discord.Embed(color=discord.Color.from_rgb(88, 166, 255))        embed.set_author(name='🎶 Music Queue')        # ── Now playing ──────────────────────────────────────────────────────        url, title, duration, is_ap = data['current_song']        if title:            elapsed = time.time() - data['play_start_time'] if data['play_start_time'] else None            ap_tag = ' 🤖' if is_ap else ''            if duration and elapsed is not None:                bar = progress_bar(elapsed, duration, width=14)                np_line = (f'[{title}](<{url}>){ap_tag}\n'                           f'`{fmt_duration(elapsed)}` {bar} `{fmt_duration(duration)}`')            else:                np_line = f'[{title}](<{url}>){ap_tag}'            embed.add_field(name='▶ Now Playing', value=np_line, inline=False)        # ── Queue listing ─────────────────────────────────────────────────────        if queue:            start = page * items_per_page            items = queue[start:start + items_per_page]            lines = []            for i, entry in enumerate(items):                qurl, qtitle, qdur = entry[0], entry[1], entry[2]                qap = entry[3] if len(entry) > 3 else False                ap_icon = ' 🤖' if qap else ''                dur_str = f' `{fmt_duration(qdur)}`' if qdur else ''                lines.append(f'**{i + 1 + start}.** [{qtitle}](<{qurl}>){ap_icon}{dur_str}')            ap_count = sum(1 for e in queue if len(e) > 3 and e[3])            field_name = f'Up Next — {len(queue)} song{"s" if len(queue) != 1 else ""}'            if ap_count:                field_name += f'  ({ap_count} 🤖)'            embed.add_field(name=field_name, value='\n'.join(lines) or '\u200b', inline=False)            # Footer: remaining time + status flags            footer_parts = [f'Page {page + 1}/{pages}']            known_durs = [e[2] for e in queue if len(e) > 2 and e[2]]            if known_durs:                remaining = sum(known_durs)                if data['play_start_time'] and data['current_song'][2]:                    remaining += max(0, data['current_song'][2] - (time.time() - data['play_start_time']))                footer_parts.append(f'~{fmt_duration(remaining)} remaining')            repeat_icons = {'all': '🔁 All', 'single': '🔂 One', 'off': '➡️ Off'}            footer_parts.append(f'Repeat: {repeat_icons.get(data["repeat_mode"], data["repeat_mode"])}')            if data['seamless']:                footer_parts.append('✨ Seamless')            if data['autoplay']:                footer_parts.append('🤖 Autoplay')            embed.set_footer(text='  •  '.join(footer_parts))        else:            embed.set_footer(text='Queue is empty after the current song.')        return embed    current_page = 0    message = await ctx.send(embed=get_page_embed(current_page))    if pages <= 1:        return    await message.add_reaction('⬅️')    await message.add_reaction('➡️')    def check(reaction, user):        return (user == ctx.author and str(reaction.emoji) in ['⬅️', '➡️']                and reaction.message.id == message.id)    while True:        try:            reaction, user = await bot.wait_for('reaction_add', timeout=60.0, check=check)            if str(reaction.emoji) == '➡️' and current_page < pages - 1:                current_page += 1                await message.edit(embed=get_page_embed(current_page))            elif str(reaction.emoji) == '⬅️' and current_page > 0:                current_page -= 1                await message.edit(embed=get_page_embed(current_page))            await message.remove_reaction(reaction.emoji, user)        except asyncio.TimeoutError:            try:                await message.clear_reactions()            except Exception:                pass            breakadd_help('Music', 'queue', 'Shows the current queue with progress bar, durations, and 🤖 autoplay markers')@bot.command(name='current', aliases=['np', 'nowplaying'])async def current_command(ctx):    data = get_server_data(ctx.guild.id)    if data['current_song'][1]:        await ctx.send(embed=build_now_playing_embed(data))    else:        await ctx.send(messages['QueueEmpty'])add_help('Music', 'current / np', 'Shows the current song with a live progress bar')@bot.command(name='move')async def move(ctx, from_position: int, to_position: int):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    n = len(data['queue'])    if from_position < 1 or from_position > n or to_position < 1 or to_position > n:        await ctx.send('Invalid positions in the queue!')        return    song = data['queue'].pop(from_position - 1)    data['queue'].insert(to_position - 1, song)    if from_position == 1 or to_position == 1:        data['next_stream_url'] = None        _schedule_prefetch(guild_id)    await ctx.send(f'Moved **{song[1]}** from position {from_position} to {to_position}.')add_help('Music', 'move <pos> <pos>', 'Moves a song in the queue from one position to another')@bot.command(name='remove', aliases=['delete', 'del'])async def remove(ctx, position: str = '0'):    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if position == 'all':        data['queue'] = []        data['next_stream_url'] = None        await ctx.send('Queue cleared!')        return    try:        pos = int(position)    except ValueError:        await ctx.send('Invalid position! Use a number or "all".')        return    if pos < 1 or pos > len(data['queue']):        await ctx.send('Invalid position in the queue!')        return    removed = data['queue'].pop(pos - 1)    if pos == 1:        data['next_stream_url'] = None        if data['queue']:            _schedule_prefetch(guild_id)    await ctx.send(f'Removed **{removed[1]}** from position {pos}.')add_help('Music', 'remove <pos|all>', 'Removes a song from the queue or clears it entirely')@bot.command(name='shuffle')async def shuffle_command(ctx):    import random    guild_id = ctx.guild.id    data = get_server_data(guild_id)    if not data['queue']:        await ctx.send('The queue is empty, nothing to shuffle!')        return    # Keep autoplay entries at the very end; shuffle only user-added songs    user_songs = [e for e in data['queue'] if not (len(e) > 3 and e[3])]    ap_songs   = [e for e in data['queue'] if     (len(e) > 3 and e[3])]    random.shuffle(user_songs)    data['queue'] = user_songs + ap_songs    data['next_stream_url'] = None    _schedule_prefetch(guild_id)    await ctx.send(f'🔀 Shuffled **{len(user_songs)}** songs in the queue.')add_help('Music', 'shuffle', 'Randomly shuffles user-added songs (autoplay entries stay at the end)')# ─── Playlist management ──────────────────────────────────────────────────────@bot.group(name='playlist', aliases=['pl'], invoke_without_command=True)async def playlist_command(ctx):    await ctx.send('Use subcommand: `add` / `remove` / `list` / `append` / `dump`')add_help('Music', 'playlist <add/remove/list/append/dump>', 'Playlist management commands')@playlist_command.command(name='add', aliases=['make'])async def playlist_add(ctx, name: str = None):    if not name:        await ctx.send('Please provide a playlist name!')        return    path = f'{playlists_folder}/{name}.txt'    if os.path.exists(path):        await ctx.send('Playlist already exists!')        return    os.makedirs(playlists_folder, exist_ok=True)    open(path, 'w', encoding='utf-8').close()    await ctx.send(f'**Created playlist {name}!**')@playlist_command.command(name='remove', aliases=['delete', 'del'])async def playlist_remove(ctx, name: str = None):    if not name:        await ctx.send('Please provide a playlist name!')        return    path = f'{playlists_folder}/{name}.txt'    if not os.path.exists(path):        await ctx.send('Playlist does not exist!')        return    os.remove(path)    await ctx.send(f'**Playlist {name} removed!**')@playlist_command.command(name='list')async def playlist_list(ctx):    if not os.path.exists(playlists_folder) or not os.listdir(playlists_folder):        await ctx.send('No playlists available')        return    names = [f.replace('.txt', '') for f in os.listdir(playlists_folder) if f.endswith('.txt')]    await ctx.send('# Available playlists\n' + '\n'.join(f' {n}' for n in names))@playlist_command.command(name='append')async def playlist_append(ctx, name: str = None, *, query: str = None):    if not name or not query:        await ctx.send('Usage: `!playlist append <name> <query/url>`')        return    path = f'{playlists_folder}/{name}.txt'    if not os.path.exists(path):        await ctx.send('Playlist does not exist!')        return    with open(path, 'a', encoding='utf-8') as f:        f.write('\n' + query)    await ctx.send(f'**Appended `{query}` to playlist {name}!**')@playlist_command.command(name='dump')async def playlist_dump(ctx, name: str = None):    data = get_server_data(ctx.guild.id)    if not name:        await ctx.send('Please provide a playlist name!')        return    if not data['queue']:        await ctx.send('The queue is empty, nothing to dump!')        return    path = f'{playlists_folder}/{name}.txt'    os.makedirs(playlists_folder, exist_ok=True)    if not os.path.exists(path):        await ctx.send('Playlist does not exist!')        return    try:        with open(path, 'a', encoding='utf-8') as f:            for entry in data['queue']:                if not (len(entry) > 3 and entry[3]):  # skip autoplay entries                    f.write(entry[0] + '\n')        saved = sum(1 for e in data['queue'] if not (len(e) > 3 and e[3]))        await ctx.send(f'✅ Appended **{saved}** songs to playlist **{name}**.')    except Exception as e:        print(f'Error dumping playlist: {e}')        await ctx.send('❌ Failed to append queue to playlist.')# ─── Owner tools ──────────────────────────────────────────────────────────────@is_owner()@bot.command(name='ts')async def troubleshoot(ctx):    await ctx.send('Checking...')    await ctx.send('YT DLP Outdated, Restart Bot Now!' if check_yt_dlp() == 202 else 'Everything Seems Fine!')add_help('Music', 'ts', 'Checks for yt-dlp updates; run if the bot throws yt-dlp errors')